```tsx
interface Props {
  tajuk: string;
  kiraan?: number;
  onTekan: (id: number) => void;
}
export function Kad({ tajuk, kiraan = 0, onTekan }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => { ref.current?.focus(); }, []);
  return (
    <div ref={ref} tabIndex={-1}>
      <h2>{tajuk}</h2>
      <p>{kiraan}</p>
      <button onClick={() => onTekan(7)}>Tekan</button>
    </div>
  );
}
```
Props interface eksplisit (tiada `FC` implisit-children!), ref null-disemak, event ditaip (`MouseEvent`), children ditaip jika diterima. `verbatimModuleSyntax`: import jenis dengan `import type`.

